tool.command:

ln -s $input_model_pth_path ./input_model_pth_path.$input_model_pth_path.ext;
ln -s $input_dataset_pt_path ./input_dataset_pt_path.$input_dataset_pt_path.ext;
#if $config_json:
  ln -s $config_json ./config_json.$config_json.ext;
#end if

train_model

#if $config_json:
  --config ./config_json.$config_json.ext
#end if

--input_model_pth_path ./input_model_pth_path.$input_model_pth_path.ext
--input_dataset_pt_path ./input_dataset_pt_path.$input_dataset_pt_path.ext
#if $outname_output_model_pth_path:
  --output_model_pth_path $outname_output_model_pth_path
#end if
#if $outname_output_metrics_npz_path:
  --output_metrics_npz_path $outname_output_metrics_npz_path
#end if
;

if test -f $outname_output_model_pth_path; then mv $outname_output_model_pth_path $output_model_pth_path; fi;
if test -f $outname_output_metrics_npz_path; then mv $outname_output_metrics_npz_path $output_metrics_npz_path; fi;
